import math
"""One reasoning challenge per original topic. Honest finite conditions; no extra curriculum prerequisites."""
challenges={
'5-01':('В выражении 125 · 16 + 125 · 24 − 125 · 32 найдите значение. Постарайтесь обойтись без трёх отдельных умножений.',1000,'Во всех слагаемых общий множитель 125. Получаем 125 · (16 + 24 − 32) = 125 · 8 = 1000. Вычитание тоже входит в скобки.','125*16+125*24-125*32'),
'5-02':('Число n при делении на 7 даёт остаток 6. Найдите остаток от деления n + 10 на 7.',2,'n состоит из полных семёрок и остатка 6. Прибавление 10 даёт остаточную часть 16 = 2 · 7 + 2. Ответ 2, а не 16: остаток должен быть меньше 7.','(6+10)%7'),
'5-03':('За первый день прочитали 1/3 книги, за второй — 1/3 книги. После этого осталось 18 страниц. Сколько страниц в книге?',54,'Прочитаны две трети всей книги, осталась одна треть. Если треть — 18 страниц, всего 54. Обе доли в условии относятся ко всей книге.','18/(1-Fraction(1,3)-Fraction(1,3))'),
'5-04':('Число 2,4 увеличили в 10 раз, затем из результата вычли 2,4. Во сколько раз получившееся число больше исходного?',9,'Получили 24 − 2,4 = 21,6. Делим на исходное 2,4: результат 9. Увеличение в разах — это отношение, а не разность.','(Fraction("2.4")*10-Fraction("2.4"))/Fraction("2.4")'),
'5-05':('Турист шёл 2 часа со скоростью 3 км/ч и 1 час со скоростью 6 км/ч. С какой постоянной скоростью он прошёл бы тот же путь за те же 3 часа? Ответ в км/ч.',4,'Путь 2 · 3 + 1 · 6 = 12 км. За 3 часа постоянная скорость 4 км/ч. Нельзя просто усреднить 3 и 6: время движения разное.','(2*3+1*6)/(2+1)'),
'5-06':('Прямоугольник разрезали одним прямым разрезом на два квадрата со стороной 5 см. Найдите периметр исходного прямоугольника в сантиметрах.',30,'Исходный прямоугольник имеет стороны 10 и 5 см, периметр 30 см. Сумма периметров квадратов равна 40, но общий разрез дважды учтён и не входит во внешнюю границу.','2*(5+2*5)'),
'5-07':('Прямоугольник 8 × 6 см разрезали на одинаковые квадраты со стороной 2 см. Сколько квадратов получилось?',12,'По длине помещается 8 : 2 = 4 квадрата, по ширине 6 : 2 = 3. Всего 12. Можно разделить площадь 48 на площадь квадрата 4, но не на его сторону.','8*6/(2**2)'),
'5-08':('Коробку без зазоров заполнили кубиками ребра 2 см: 4 кубика в длину, 3 в ширину и 2 в высоту. Найдите внутренний объём коробки в см³.',192,'Всего 4 · 3 · 2 = 24 кубика. Объём одного 2³ = 8 см³, общий объём 192 см³. Число кубиков и объём — разные величины.','4*3*2*2**3'),
'6-01':('Натуральные числа a и b имеют НОД 6 и НОК 72. Число a равно 18. Найдите b.',24,'Произведение чисел равно произведению НОД и НОК: b = 6 · 72 : 18 = 24. Проверяем НОД(18, 24) = 6 и НОК = 72.','6*72/18'),
'6-02':('От ленты отрезали 1/3 её длины, затем 1/4 оставшейся части. Осталось 6 м. Какова первоначальная длина в метрах?',12,'После первого отрезания осталось 2/3, после второго — 3/4 от этих 2/3, то есть 1/2 исходной длины. Значит исходная длина 12 м. Вторая доля берётся от остатка.','6/((1-Fraction(1,3))*(1-Fraction(1,4)))'),
'6-03':('Цену сначала снизили на 20%. На сколько процентов нужно повысить новую цену, чтобы вернуть исходную?',25,'Для удобства исходная цена 100, новая 80. Нужно добавить 20 от базы 80: 20/80 · 100% = 25%. Обратное изменение не равно 20%.','(1/(1-.2)-1)*100'),
'6-04':('Мальчики и девочки относятся как 2 : 3. После прихода ещё четырёх мальчиков их стало столько же, сколько девочек. Сколько учеников было первоначально?',20,'Пусть мальчиков 2 части, девочек 3. Разница в одну часть равна 4, всего 5 частей — 20 учеников. Четыре новых ученика в первоначальный состав не входят.','4/(3-2)*(2+3)'),
'6-05':('Утром было −4 °C. К полудню температура поднялась на 7 градусов, к вечеру упала на 9. На сколько градусов вечерняя температура ниже утренней?',2,'Вечером −4 + 7 − 9 = −6 °C. По сравнению с −4 это ниже на 2 градуса. Искомое изменение положительно, хотя температура отрицательна.','(-4)-(-4+7-9)'),
'6-06':('Сколько целых чисел x удовлетворяют |x| < 4?',7,'Подходят −3, −2, −1, 0, 1, 2, 3. Их 7. Числа ±4 не входят из-за строгого знака, а ноль входит.','len([x for x in range(-10,11) if abs(x)<4])'),
'6-07':('Точка A(−3; 2) сдвинута на 5 единиц вправо, затем на 4 вниз. Найдите сумму координат полученной точки.',0,'Получаем (2; −2). Сумма равна нулю. Движение вниз уменьшает ординату, а не её модуль.','(-3+5)+(2-4)'),
'6-08':('Точку A(3; −4) сначала отразили относительно оси x, затем относительно оси y. Найдите сумму координат конечной точки.',1,'После первого отражения (3; 4), после второго (−3; 4). Сумма 1. Два отражения относительно разных осей не возвращают исходную точку.','-3+4'),
'7-01':('Уравнение 4(x − a) = 4x − 12 имеет бесконечно много решений. Найдите a.',3,'Члены 4x сокращаются. Чтобы равенство выполнялось при любом x, нужно −4a = −12, откуда a = 3. Делить на разность коэффициентов при x нельзя: она нулевая.','12/4'),
'7-02':('Найдите последнюю цифру числа 2²⁰ + 3²⁰.',7,'Последние цифры степеней 2 повторяются 2, 4, 8, 6; степеней 3 — 3, 9, 7, 1. Показатель 20 кратен 4, поэтому последние цифры 6 и 1, в сумме 7.','(2**20+3**20)%10'),
'7-03':('Числа a и b удовлетворяют a + b = 10 и ab = 21. Найдите (a − b)², не находя сами числа.',16,'(a − b)² = (a + b)² − 4ab = 100 − 84 = 16. Для квадрата разности не требуется выбирать порядок a и b.','10**2-4*21'),
'7-04':('График линейной функции проходит через A(−2; −1) и B(4; 11). Найдите сумму её значений при x = −1 и x = 3.',10,'Наклон (11 + 1)/6 = 2, свободный член 3. Значения равны 1 и 9, сумма 10. Можно заметить, что аргументы симметричны относительно 1, а сумма значений равна 2f(1).','(2*(-1)+3)+(2*3+3)'),
'7-05':('В системе 2x + 3y = 7 и 4x + 6y = 14 найдите значение выражения 6x + 9y.',21,'Второе уравнение повторяет первое, поэтому x и y отдельно не определены. Но искомое выражение втрое больше левой части первого: 3 · 7 = 21.','3*7'),
'7-06':('При пересечении двух прямых сумма трёх из четырёх углов равна 250°. Найдите наименьший из четырёх углов в градусах.',70,'Все четыре угла дают 360°, значит четвёртый 110°. Смежный ему 70°, вертикальные повторяют эти значения. Наименьший 70°, а не 110°.','min(360-250,180-(360-250))'),
'7-07':('В равнобедренном треугольнике один угол вдвое больше другого. Найдите все возможные значения угла при вершине в градусах.',([36,90],'36; 90'),'Если вершина вдвое больше основания, 2b + 2b = 180°, вершина 90°. Если основание вдвое больше вершины, a + 4a = 180°, вершина 36°. Нужно рассмотреть оба случая.','[180/5,180/2]'),
'7-08':('Среднее четырёх чисел равно 10, их медиана равна 9. Наименьшее число 3. Найдите наибольшее.',19,'Сумма всех чисел 40. Медиана четырёх чисел — среднее двух средних, значит их сумма 18. Наибольшее равно 40 − 18 − 3 = 19.','4*10-2*9-3'),
'7-09':('В первых 20 опытах событие появилось 5 раз. После ещё 30 опытов общая частота стала 0,4. Сколько раз событие появилось в последних 30 опытах?',15,'Всего 50 опытов, появлений 0,4 · 50 = 20. В новых опытах 20 − 5 = 15. Нельзя умножать общую частоту только на 30.','.4*(20+30)-5'),
'7-10':('В смеси 10 кг сока доля сиропа 20%. Сколько килограммов воды нужно добавить, чтобы доля сиропа стала 8%? Массы складываются, сироп не теряется.',15,'Сиропа 2 кг. При доле 8% общая масса должна стать 2/0,08 = 25 кг. Добавить нужно 25 − 10 = 15 кг.','10*.2/.08-10'),
'7-11':('У равнобедренного треугольника две разные длины сторон: 4 см и 9 см. Найдите периметр в сантиметрах.',22,'Равными не могут быть стороны по 4 см: 4 + 4 < 9, треугольник не существует. Поэтому боковые стороны по 9 см, основание 4 см, периметр 22 см.','9+9+4'),
'7-12':('В группе 40 человек. 25 изучают английский, 22 — французский, каждый изучает хотя бы один из двух языков. Сколько человек изучают оба?',7,'Сумма 25 + 22 дважды считает тех, кто изучает оба языка. Вычитаем общую численность: 47 − 40 = 7.','25+22-40'),
'8-01':('Вычислите √((√5 − 3)²) + √5.',3,'Корень из квадрата равен модулю. Так как √5 < 3, |√5 − 3| = 3 − √5. После прибавления √5 остаётся 3.','sqrt((sqrt(5)-3)**2)+sqrt(5)'),
'8-02':('Уравнение x² − 6x + c = 0 имеет два корня, один втрое больше другого. Найдите c.',6.75,'Пусть корни r и 3r. По Виету 4r = 6, r = 1,5. Произведение c = 3r² = 6,75. Корни действительны и различны.','3*(6/4)**2'),
'8-03':('Сколько действительных решений имеет уравнение (x² − 1)/(x − 1) = 2?',0,'ОДЗ: x ≠ 1. После сокращения получаем x + 1 = 2, то есть x = 1, но оно исключено. Решений нет; сокращение не отменяет ОДЗ.','len([x for x in [1] if x!=1])'),
'8-04':('Сколько целых решений имеет двойное неравенство −2 < (1 − 3x)/2 ≤ 4?',4,'Умножаем на 2: −4 < 1 − 3x ≤ 8. После преобразования −7/3 ≤ x < 5/3. Целые −2, −1, 0, 1 — четыре.','len([x for x in range(-10,11) if -2<(1-3*x)/2<=4])'),
'8-05':('Высота равнобедренного треугольника, проведённая к основанию, равна 12 см, боковая сторона 13 см. Найдите периметр в сантиметрах.',36,'Высота делит основание пополам. Половина основания √(169 − 144) = 5 см, всё основание 10 см. Периметр 13 + 13 + 10 = 36 см.','2*13+2*sqrt(13**2-12**2)'),
'8-06':('В параллелограмме стороны 6 см и 10 см. Высота к одной из этих сторон равна 8 см. Найдите площадь в см².',48,'Высота к стороне 10 не может превышать другую сторону 6. Поэтому высота 8 проведена к стороне 6. Площадь 6 · 8 = 48 см². Важно определить допустимую пару основания и высоты.','6*8'),
'8-07':('Площади двух подобных треугольников относятся как 4 : 9. Периметр большего 30 см. Найдите периметр меньшего в сантиметрах.',20,'Отношение длин равно корню из отношения площадей: 2 : 3. Поэтому меньший периметр 30 · 2/3 = 20 см.','30*sqrt(4/9)'),
'8-08':('Дважды независимо бросают правильный кубик. Известно, что сумма очков равна 5. Найдите вероятность того, что на первом кубике выпало 2.',(.25,'1/4'),'Под условием остаются четыре равновозможные упорядоченные пары: (1; 4), (2; 3), (3; 2), (4; 1). Подходит одна. Условие меняет множество исходов.','len([(a,b) for a in range(1,7) for b in range(1,7) if a+b==5 and a==2])/len([(a,b) for a in range(1,7) for b in range(1,7) if a+b==5])'),
'8-09':('Набор имеет среднее 10 и дисперсию 4. Каждое число заменили числом 20 − 3x. Найдите новую дисперсию.',36,'Сдвиг на 20 не влияет на отклонения. Умножение на −3 меняет отклонения в −3 раза, их квадраты — в 9 раз. Дисперсия 9 · 4 = 36.','(-3)**2*4'),
'8-10':('Графики y = 12/x и y = x + 1 пересекаются в двух точках. Найдите сумму абсцисс точек пересечения.',-1,'x ≠ 0. Уравнение пересечения x² + x − 12 = 0 имеет корни 3 и −4, оба допустимы. Сумма −1. Отрицательная ветвь гиперболы тоже участвует.','sum(qroots(1,1,-12))'),
'8-11':('Вписанный четырёхугольник ABCD имеет углы A = 2x + 10°, C = 4x − 4°. Найдите угол A в градусах.',68,'Противоположные углы в сумме 180°: 6x + 6 = 180, x = 29. Угол A равен 68°. Здесь не нужно считать сумму только двух углов как 360°.','2*((180-6)/6)+10'),
'8-12':('A и B независимы, P(A ∪ B) = 0,8, P(A) = 0,5. Найдите P(B).',.6,'Пусть p = P(B). Формула объединения даёт 0,5 + p − 0,5p = 0,8. Тогда 0,5p = 0,3, p = 0,6. Суммировать вероятности без вычитания пересечения нельзя.','(.8-.5)/(1-.5)'),
'9-01':('В арифметической прогрессии a₂ + a₈ = 20. Найдите сумму первых девяти членов.',90,'Симметричные члены a₂ и a₈ в сумме равны 2a₅, значит a₅ = 10. Сумма девяти членов равна 9a₅ = 90. Первый член отдельно не нужен.','9*20/2'),
'9-02':('В геометрической прогрессии b₁ = 4, b₃ = 36. Найдите все возможные значения b₂.',([-12,12],'−12; 12'),'q² = 36/4 = 9, поэтому q = ±3. Второй член равен ±12. Условие не задаёт знак знаменателя, оба случая допустимы.','[-sqrt(4*36),sqrt(4*36)]'),
'9-03':('При каких значениях a парабола y = x² − 2ax + a + 2 касается оси x? Укажите все значения.',([-1,2],'−1; 2'),'Касание означает нулевой дискриминант: 4a² − 4a − 8 = 0. Получаем a² − a − 2 = 0, откуда a = −1 или 2.','qroots(1,-1,-2)'),
'9-04':('Сколько действительных корней имеет уравнение x⁴ + x² − 2 = 0?',2,'Замена t = x² даёт (t + 2)(t − 1) = 0. Отрицательное t = −2 невозможно, а t = 1 даёт x = ±1. Всего два корня, а не четыре.','len(biquad(1,1,-2))'),
'9-05':('Векторы a и b имеют длины 3 и 4, а |a + b| = 5. Найдите |a − b|.',5,'|a + b|² = 9 + 16 + 2a · b = 25, значит a · b = 0. Тогда |a − b|² = 9 + 16 − 0 = 25, длина 5.','sqrt(2*(3**2+4**2)-5**2)'),
'9-06':('Радиус круга увеличили на 20%. На сколько процентов увеличилась площадь?',44,'Площадь пропорциональна квадрату радиуса: множитель 1,2² = 1,44. Рост 44%, а не 20% и не 40%.','(1.2**2-1)*100'),
'9-07':('Две стороны треугольника 5 и 8 см, площадь равна 10 см². Найдите все возможные значения косинуса угла между этими сторонами.',([math.sqrt(3)/2,-math.sqrt(3)/2],'−√3/2; √3/2'),'Из S = ab sin C/2 получаем sin C = 1/2. Угол может быть 30° или 150°, поэтому косинус равен ±√3/2. Оба треугольника невырождены.','[-sqrt(1-(2*10/(5*8))**2),sqrt(1-(2*10/(5*8))**2)]'),
'9-08':('В ряд случайно расставляют пять разных книг. Две заранее указанные книги должны стоять рядом. Сколько расстановок возможно?',48,'Считаем пару одним блоком: четыре объекта можно расставить 4! способами. Внутри блока два порядка. Всего 2 · 24 = 48.','factorial(4)*2'),
'9-09':('Правильную монету бросили трижды. Известно, что орёл выпал хотя бы один раз. Найдите вероятность ровно двух орлов.',(3/7,'3/7'),'Из восьми равновозможных исходов условие исключает РРР. Из оставшихся семи ровно два орла в трёх. Вероятность 3/7, а не 3/8.','comb(3,2)/(2**3-1)'),
'9-10':('Сколько целых решений имеет неравенство (x − 2)² ≤ 0?',1,'Квадрат всегда неотрицателен. Условие возможно лишь при x − 2 = 0, то есть x = 2. Решение одно, несмотря на знак ≤.','len([x for x in range(-10,11) if (x-2)**2<=0])'),
'9-11':('Окружность (x − 2)² + (y + 1)² = 9 пересекает ось x. Найдите сумму абсцисс двух точек пересечения.',4,'На оси x имеем y = 0, поэтому (x − 2)² = 8. Корни симметричны относительно 2, их сумма 4. Значения корней отдельно находить не требуется.','sum(qroots(1,-4,-4))'),
'9-12':('Лотерея платит 100 рублей с вероятностью 0,2, иначе ничего. Билет стоит 15 рублей. Найдите ожидаемый чистый результат покупки трёх билетов в рублях.',15,'Ожидаемый результат одного билета 100 · 0,2 − 15 = 5 рублей. Ожидания складываются: 15 рублей. Независимость для сложения ожиданий не требуется.','3*(100*.2-15)'),
'10-01':('Решите √(x² − 4x + 4) = x − 2. В ответе укажите наименьшее допустимое x.',2,'Левая часть |x − 2|. Равенство |u| = u верно при u ≥ 0, значит x ≥ 2. Наименьшее 2; нельзя заменять корень на x − 2 для всех x.','2'),
'10-02':('Решите уравнение logₓ(16) = log₂(x). Укажите все действительные корни.',([.25,4],'1/4; 4'),'ОДЗ x > 0, x ≠ 1. Пусть t = log₂(x), t ≠ 0. Тогда logₓ(16) = 4/t. Из t² = 4 получаем t = ±2, откуда x = 1/4 или 4. Оба основания допустимы.','[2**t for t in qroots(1,0,-4)]'),
'10-03':('Решите уравнение 4ˣ − 2 · 2ˣ − 8 = 0. Укажите все действительные корни.',([2],'2'),'При t = 2ˣ > 0 получаем t² − 2t − 8 = 0, t = 4 или −2. Отрицательное значение t невозможно. Поэтому x = 2 — единственный корень.','[log(t,2) for t in qroots(1,-2,-8) if t>0]'),
'10-04':('Найдите sin α + cos α, если sin(2α) = −1.',0,'Квадрат суммы равен 1 + sin(2α) = 0. Значит сама сумма равна нулю. Отдельные sin α и cos α могут иметь разные знаки, но сумма определяется однозначно.','sqrt(1+(-1))'),
'10-05':('Сколько корней имеет sin² x = sin x на отрезке [0°; 360°]?',4,'sin x(sin x − 1) = 0. Корни на закрытом отрезке: 0°, 180°, 360° и 90°. Концы 0° и 360° — разные значения аргумента, поэтому всего четыре.','len([x for x in range(361) if abs(sin(x*pi/180)**2-sin(x*pi/180))<1e-9])'),
'10-06':('Остаток P(x) при делении на x − 1 равен 3, а на x + 1 равен 7. Остаток при делении на x² − 1 имеет вид ax + b. Найдите b.',5,'По теореме Безу a + b = 3 и −a + b = 7. Складываем: 2b = 10, b = 5. Сам многочлен P знать не требуется.','(3+7)/2'),
'10-07':('Для системы ax + y = 1, x + ay = 1 найдите все значения a, при которых она не имеет единственного решения.',([-1,1],'−1; 1'),'Определитель a² − 1 равен нулю при ±1. При a = 1 решений бесконечно много, при a = −1 их нет. Оба случая подходят формулировке «не имеет единственного решения».','qroots(1,0,-1)'),
'10-08':('Для f(x) = x² определена обратная функция после ограничения области определения отрезком [−3; 0]. Найдите f⁻¹(4).',-2,'На выбранном отрезке x² убывает и обратима. Из x² = 4 подходит только x = −2. Ответ +2 лежит вне выбранной области.','[x for x in qroots(1,0,-4) if -3<=x<=0][0]'),
'10-09':('Бесконечная геометрическая прогрессия имеет сумму 6, а сумма её членов с чётными номерами равна 2. Найдите знаменатель q.',(.5,'1/2'),'Сумма чётных членов равна b₁q/(1 − q²). Делим на общую сумму b₁/(1 − q): 2/6 = q/(1 + q). Получаем q = 1/2. Сходимость |q| < 1 выполнена.','2/(6-2)'),
'10-10':('К графику f(x) = x³ в точках x = a и x = −a проведены касательные. При a > 0 они параллельны и расстояние между их точками пересечения с осью y равно 32. Найдите a.',2,'Касательная в a имеет вид y = 3a²x − 2a³, в −a — y = 3a²x + 2a³. Разность пересечений равна 4a³ = 32, поэтому a = 2. Это расстояние на оси y, а не расстояние между прямыми.','(32/4)**(1/3)'),
'10-11':('Точка A удалена от плоскости на 6 см. Наклонные AB и AC равны 10 см. Найдите длину BC, если проекции HB и HC направлены противоположно по одной прямой в плоскости.',16,'Обе проекции имеют длину √(100 − 36) = 8. При противоположных направлениях H лежит между B и C, поэтому BC = 16. Равенство наклонных само по себе не задаёт угол между проекциями — он явно указан.','2*sqrt(10**2-6**2)'),
'10-12':('У прямоугольного параллелепипеда площади трёх граней с общей вершиной равны 6, 10 и 15 см². Найдите сумму длин трёх рёбер из этой вершины в сантиметрах.',10,'Пусть ab = 6, ac = 10, bc = 15. Тогда a² = 60/15 = 4, a = 2; b = 3, c = 5. Сумма 10. Положительность длин позволяет выбрать положительные корни.','sqrt(6*10/15)+sqrt(6*15/10)+sqrt(10*15/6)'),
'10-13':('Векторы a = (1; 2; 3), b = (2; 4; 6). Найдите число действительных t, при которых a + tb является единичным вектором.',2,'b = 2a, длина a равна √14. Условие |1 + 2t|√14 = 1 даёт два значения t. При модуле необходимо рассмотреть оба знака.','len(qroots(56,56,13))'),
'10-14':('В мешке один обычный кубик и один кубик с шестёрками на всех гранях. Кубик выбирают равновероятно и бросают. Выпала шестёрка. Найдите вероятность, что выбран обычный кубик.',(1/7,'1/7'),'Совместная вероятность обычного кубика и шестёрки 1/12. Вероятность шестёрки 1/12 + 1/2 = 7/12. По Байесу искомая вероятность 1/7, а не 1/2.','(.5/6)/(.5/6+.5)'),
'10-15':('Правильную монету бросают до первого орла, но не более трёх раз. Найдите вероятность того, что будет сделано ровно три броска.',(.25,'1/4'),'Третий бросок состоится, если первые два — решки. Его собственный результат уже не важен. Вероятность (1/2)² = 1/4, а не 1/8.','.5**2'),
'10-16':('X и Y независимы, E(X) = E(Y) = 0, D(X) = 2, D(Y) = 3. Найдите E((X + Y)²).',5,'E(X + Y) = 0. Поэтому ожидание квадрата равно дисперсии суммы, а по независимости она равна 2 + 3 = 5. Независимость нужна для исчезновения смешанного слагаемого.','2+3'),
'11-01':('Число z удовлетворяет z + сопряжённое(z) = 6 и |z| = 5. Найдите все возможные мнимые части z.',([-4,4],'−4; 4'),'Сумма с сопряжённым даёт удвоенную действительную часть: Re z = 3. Из 3² + (Im z)² = 25 получаем Im z = ±4. Оба знака допустимы.','qroots(1,0,3**2-5**2)'),
'11-02':('Найдите остаток от деления суммы 1! + 2! + 3! + … + 20! на 12.',9,'Начиная с 4! каждый член делится на 12. Осталось 1 + 2 + 6 = 9. Не нужно вычислять большие факториалы.','sum(factorial(k) for k in range(1,21))%12'),
'11-03':('Сколько целых решений имеет log₂((x − 1)²) < 2?',2,'ОДЗ x ≠ 1. Неравенство даёт (x − 1)² < 4, то есть −1 < x < 3. Целые 0, 1, 2, но 1 исключён ОДЗ. Остались два.','len([x for x in range(-10,11) if 0<(x-1)**2<4])'),
'11-04':('При каких значениях a уравнение x² − 2ax + a² − 1 = 0 имеет ровно один положительный корень? Найдите наибольшее такое a.',1,'Корни a − 1 и a + 1. Ровно один положителен при −1 < a ≤ 1. При a = 1 корни 0 и 2, ноль не положителен. Наибольшее a равно 1.','1'),
'11-05':('Функция f(x) = x³ − 3x² + 3x + 7 имеет стационарную точку. Найдите значение функции в ней.',8,'f′(x) = 3(x − 1)², стационарная точка x = 1, f(1) = 8. Это не экстремум: производная не меняет знак. Стационарность и экстремум — разные понятия.','1**3-3*1**2+3*1+7'),
'11-06':('Найдите площадь между графиком y = x³ и осью x на отрезке [−1; 1].',(.5,'1/2'),'Интеграл нечётной функции на симметричном отрезке равен нулю, но площадь складывается из положительных частей: 2 · интеграл x³ от 0 до 1 = 1/2.','2*integral_poly([1,0,0,0],0,1)'),
'11-07':('Сколько решений имеет sin x = 0 на полуинтервале [−360°; 360°)?',4,'Корни кратны 180°. Входят −360°, −180°, 0°, 180°; правая граница 360° исключена. Получаем четыре корня.','len([x for x in range(-360,360) if abs(sin(x*pi/180))<1e-9])'),
'11-08':('Цилиндр и конус имеют одинаковые основания и высоты. Их суммарный объём 48 см³. Найдите объём конуса в см³.',12,'Объём цилиндра втрое больше объёма конуса. Сумма — четыре объёма конуса, поэтому 48/4 = 12. Равные основания и высоты не означают равные объёмы.','48/(3+1)'),
'11-09':('Площадь поверхности шара увеличилась в 9 раз. Во сколько раз увеличился объём шара?',27,'Площадь пропорциональна R², поэтому радиус вырос в 3 раза. Объём пропорционален R³, значит вырос в 27 раз.','sqrt(9)**3'),
'11-10':('Пирамиду пересекли плоскостью, параллельной основанию. Площадь малого сечения равна четверти площади основания. Объём исходной пирамиды 64 см³. Найдите объём малой пирамиды у вершины.',8,'Отношение линейных размеров — корень из 1/4, то есть 1/2. Отношение объёмов 1/8. Малый объём 64/8 = 8 см³. Площадь и объём масштабируются по-разному.','64*(sqrt(1/4))**3'),
'11-11':('E(X) = 0, D(X) = 9. Какую наиболее сильную верхнюю границу для P(|X| ≥ 2) дают вместе неравенство Чебышёва и аксиомы вероятности?',1,'Чебышёв даёт 9/4, но любая вероятность не больше 1. Берём минимум 1 и 9/4, получаем 1. Граница 2,25 не может быть значением вероятности.','min(1,9/2**2)'),
'11-12':('X равномерно распределена на [0; 10]. Известно X > 4. Найдите P(X < 7 | X > 4).',(.5,'1/2'),'Условие оставляет интервал (4; 10) длины 6. Благоприятная часть (4; 7) имеет длину 3. Отношение 1/2; исходная длина 10 уже не знаменатель.','(7-4)/(10-4)'),
'11-13':('X имеет распределение Пуассона с λ = 2. Известно, что X равно 0 или 1. Найдите условную вероятность X = 1.',(2/3,'2/3'),'P(X = 0) = e⁻², P(X = 1) = 2e⁻². После условия нормируем: 2e⁻²/(3e⁻²) = 2/3. Общий множитель сокращается.','(2*exp(-2))/(exp(-2)+2*exp(-2))'),
'11-14':('X имеет ненулевую дисперсию, Y = 7 − 2X. Найдите коэффициент корреляции X и Y.',-1,'Связь точно линейная с отрицательным наклоном, поэтому корреляция −1. Сдвиг на 7 не влияет; ненулевая дисперсия нужна, чтобы коэффициент был определён.','-2/sqrt((-2)**2)')
}
for tid,row in challenges.items():add(tid,*row,options={'difficulty':'Суперсложный','tricky':True,'challenge':True})
